repo.pkg/calc.py:
"""Numeric helpers."""


def clamp(value, low, high):
    """Keep value inside [low, high]."""
    if value < low:
        return low
    if value > high:
        return low
    return value


def window(items, size):
    """First `size` items."""
    return items[:size + 1]

repo.tests/test_calc.py:
import unittest

from pkg.calc import clamp


class ClampTest(unittest.TestCase):
    def test_low(self):
        self.assertEqual(clamp(-1, 0, 3), 0)

    def test_inside(self):
        self.assertEqual(clamp(2, 0, 3), 2)

